"use client";

// app/benchmarks/page.tsx
//
// Live benchmark results, fetched from the yatta.js repo's benchmarks.json
// (generated by CI on every benchmark run).

import { useEffect, useLayoutEffect, useRef, useState } from "react";
import Link from "next/link";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import SiteNav from "@/components/site-nav";

gsap.registerPlugin(ScrollTrigger);

interface FrameworkResult {
  name: string;
  requests_per_sec: number;
  vs_yatta: number;
  latency_ms: { avg: number; p50: number; p95: number; p99: number };
}

interface BenchmarkData {
  generated_at: string;
  commit: string;
  commit_short: string;
  commit_url: string | null;
  runner: string;
  runtime: string;
  comparison: {
    generated_at: string;
    route: string;
    load: { requests: number; concurrency: number; keep_alive: boolean };
    frameworks: FrameworkResult[];
  } | null;
}

const JSON_URL =
  "https://raw.githubusercontent.com/psrockstar098/yatta.js/main/benchmarks.json";

export default function BenchmarksPage() {
  const rootRef = useRef<HTMLDivElement>(null);
  const [data, setData] = useState<BenchmarkData | null>(null);
  const [error, setError] = useState(false);

  useEffect(() => {
    fetch(JSON_URL)
      .then((r) => {
        if (!r.ok) throw new Error("fetch failed");
        return r.json();
      })
      .then(setData)
      .catch(() => setError(true));
  }, []);

  useLayoutEffect(() => {
    const root = rootRef.current;
    if (!root || !data) return;
    const ctx = gsap.context(() => {
      gsap.utils.toArray<HTMLElement>("[data-animate-bar]").forEach((bar) => {
        const target = parseFloat(bar.dataset.target || "0");
        gsap.fromTo(bar, { scaleX: 0 }, {
          scaleX: target, duration: 1.2, ease: "power3.out",
          scrollTrigger: { trigger: bar, start: "top 90%" },
        });
      });
      gsap.utils.toArray<HTMLElement>("[data-fade-in]").forEach((el) => {
        gsap.fromTo(el, { opacity: 0, y: 30 }, {
          opacity: 1, y: 0, duration: 0.8, ease: "power2.out",
          scrollTrigger: { trigger: el, start: "top 85%" },
        });
      });
      gsap.fromTo("[data-hero-title]", { opacity: 0, y: 50 }, { opacity: 1, y: 0, duration: 1, ease: "power3.out", delay: 0.2 });
    }, root);
    return () => ctx.revert();
  }, [data]);

  const frameworks = data?.comparison?.frameworks ?? [];
  const maxRps = Math.max(1, ...frameworks.map((f) => f.requests_per_sec));

  return (
    <div ref={rootRef} className="min-h-screen bg-[#050505] text-[#f3eed7]">
      <SiteNav />
      <section className="relative overflow-hidden px-5 pt-32 pb-16 sm:px-8 sm:pt-40">
        <div className="pointer-events-none absolute inset-0 opacity-30" style={{ background: "radial-gradient(ellipse 80% 60% at 50% 0%, rgba(16,185,129,0.15), transparent)" }} />
        <div className="relative mx-auto max-w-5xl">
          <p className="font-mono text-[11px] uppercase tracking-[0.3em] text-emerald-400/80">Live from CI</p>
          <h1 data-hero-title className="font-bebas mt-4 text-[clamp(3rem,10vw,7rem)] leading-[0.9] tracking-wide">LIVE<br /><span className="text-emerald-400">BENCHMARKS</span></h1>
          <p className="mt-6 max-w-2xl text-lg text-[#f3eed7]/60">
            Regenerated by GitHub Actions on every push to main. Real numbers from real CI runners.
          </p>
          {data && (
            <div className="mt-6 flex flex-wrap gap-4 font-mono text-xs text-[#f3eed7]/40">
              <span>Runner: {data.runner}</span>
              <span>Runtime: {data.runtime}</span>
              {data.commit_url ? (
                <a href={data.commit_url} target="_blank" rel="noopener noreferrer" className="text-emerald-400/80 hover:text-emerald-300">
                  Commit {data.commit_short}
                </a>
              ) : null}
              <span>{new Date(data.generated_at).toLocaleDateString()}</span>
            </div>
          )}
        </div>
      </section>

      <section className="px-5 py-16 sm:px-8">
        <div className="mx-auto max-w-5xl">
          {!data && !error && (
            <p className="font-mono text-sm text-[#f3eed7]/50">Loading live results…</p>
          )}
          {error && (
            <div className="rounded-2xl border border-amber-500/20 bg-amber-500/5 p-6">
              <p className="text-amber-300">Benchmark data not available yet.</p>
              <p className="mt-2 text-sm text-[#f3eed7]/60">CI generates benchmarks.json on the next push to main. Check back soon.</p>
            </div>
          )}
          {data?.comparison && (
            <>
              <h2 data-fade-in className="font-bebas text-4xl tracking-wide sm:text-5xl">FRAMEWORK COMPARISON</h2>
              <p data-fade-in className="mt-2 font-mono text-xs uppercase tracking-[0.2em] text-[#f3eed7]/40">
                {data.comparison.route} · {data.comparison.load.requests.toLocaleString()} requests · {data.comparison.load.concurrency} concurrent
              </p>
              <div className="mt-10 space-y-6">
                {[...frameworks].sort((a, b) => b.requests_per_sec - a.requests_per_sec).map((f) => {
                  const isYatta = f.name === "Yatta";
                  return (
                    <div key={f.name} data-fade-in className={`rounded-2xl border p-6 ${isYatta ? "border-emerald-500/30 bg-emerald-500/[0.07]" : "border-white/5 bg-white/[0.02]"}`}>
                      <div className="flex items-baseline justify-between">
                        <span className={`font-mono text-sm uppercase tracking-wider ${isYatta ? "text-emerald-400" : "text-[#f3eed7]/80"}`}>
                          {f.name}
                          {isYatta && <span className="ml-2 rounded-full bg-emerald-500/20 px-2 py-0.5 text-[10px] text-emerald-300">this framework</span>}
                        </span>
                        <span className="font-mono text-lg">{f.requests_per_sec.toLocaleString()} <span className="text-xs text-[#f3eed7]/40">req/s</span></span>
                      </div>
                      <div className="mt-3 h-3 overflow-hidden rounded-full bg-white/5">
                        <div data-animate-bar data-target={(f.requests_per_sec / maxRps).toFixed(3)} className={`h-full origin-left rounded-full ${isYatta ? "bg-gradient-to-r from-emerald-500 to-emerald-300" : "bg-[#f3eed7]/20"}`} style={{ transform: "scaleX(0)" }} />
                      </div>
                      <div className="mt-4 grid grid-cols-2 gap-2 font-mono text-xs sm:grid-cols-5">
                        <div><span className="text-[#f3eed7]/35">vs Yatta </span><span className={isYatta ? "text-emerald-300" : "text-[#f3eed7]/70"}>{f.vs_yatta.toFixed(2)}x</span></div>
                        <div><span className="text-[#f3eed7]/35">avg </span><span className="text-[#f3eed7]/70">{f.latency_ms.avg}ms</span></div>
                        <div><span className="text-[#f3eed7]/35">p50 </span><span className="text-[#f3eed7]/70">{f.latency_ms.p50}ms</span></div>
                        <div><span className="text-[#f3eed7]/35">p95 </span><span className="text-[#f3eed7]/70">{f.latency_ms.p95}ms</span></div>
                        <div><span className="text-[#f3eed7]/35">p99 </span><span className="text-[#f3eed7]/70">{f.latency_ms.p99}ms</span></div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </>
          )}
        </div>
      </section>

      <section className="px-5 py-20 sm:px-8">
        <div data-fade-in className="mx-auto max-w-3xl text-center">
          <div className="flex flex-col gap-3 sm:flex-row sm:justify-center">
            <Link href="/compare" className="rounded-full bg-emerald-500 px-8 py-4 font-mono text-sm uppercase tracking-[0.15em] text-black hover:bg-emerald-400">Full comparison</Link>
            <Link href="/docs" className="rounded-full border border-white/20 px-8 py-4 font-mono text-sm uppercase tracking-[0.15em] text-[#f3eed7] hover:bg-white/5">Read the docs</Link>
          </div>
        </div>
      </section>
    </div>
  );
}
